{
  "items": [
    {
      "title": "German Longitudinal Election Study (GLES) – Election Studies 2009–2025",
      "url_or_doi": "https://www.gesis.org/en/gles/data-and-documentation",
      "justification": "One of the most comprehensive datasets for studying political behaviour and attitudes in Germany during the 2010s and 2020s. Covers federal elections in 2013, 2017, 2021 and 2025. Includes voting behaviour, party identification, political preferences, ideological orientations, political trust, electoral participation and attitudes toward candidates. Contains cross-sectional surveys, panel studies and election campaign surveys. Particularly suitable for analysing electoral change, political polarization and the rise of parties such as the AfD."
    },
    {
      "title": "German General Social Survey (ALLBUS) – 1980–2025",
      "url_or_doi": "https://www.gesis.org/en/allbus/data-and-documentation",
      "justification": "A major representative survey of the German population that provides repeated measurements of social and political attitudes. Includes surveys throughout the 2010s and 2020s, covering political interest, political participation, trust in institutions, ideological orientations, attitudes toward immigration, social inequality and democracy. Particularly valuable for investigating long-term changes in political values and comparing East and West Germany. The cumulative datasets enable analysis across multiple decades."
    },
    {
      "title": "Politbarometer – German Political Opinion Surveys, 1977–2024",
      "url_or_doi": "https://doi.org/10.4232/1.14611",
      "justification": "A harmonized dataset of German political opinion surveys conducted approximately monthly by Forschungsgruppe Wahlen for ZDF. Covers the entire 2010s and much of the 2020s. Contains information about voting intentions, party preferences, political leaders, government evaluations, ideological orientations and important political issues. Its high survey frequency makes it particularly useful for tracking changes in public opinion during political crises, elections and government transitions."
    },
    {
      "title": "Politbarometer 2024 – Cumulated Dataset",
      "url_or_doi": "https://doi.org/10.4232/1.14517",
      "justification": "A detailed dataset containing German political opinion surveys conducted throughout 2024. Includes voting intentions, party evaluations, government satisfaction, coalition preferences and attitudes toward major political issues. Particularly useful for investigating the changing German party system, support for the AfD and BSW, attitudes toward immigration and climate policy, and evaluations of the governing coalition."
    },
    {
      "title": "GLES Tracking 2009–2026 – Cumulative Dataset",
      "url_or_doi": "https://search.gesis.org/research_data/ZA6832",
      "justification": "A cumulative survey dataset specifically designed to examine changes in political attitudes and electoral preferences in Germany over time. Includes repeated observations across the 2010s and 2020s, allowing researchers to analyse party support, political trust, ideological positions, government evaluations and responses to political developments. Particularly suitable for studying political polarization, electoral volatility and changing public attitudes between federal elections."
    },
    {
      "title": "GLES Rolling Cross-Section Studies – Federal Elections 2013, 2017, 2021 and 2025",
      "url_or_doi": "https://www.gesis.org/en/gles/data-and-documentation",
      "justification": "A collection of election-period surveys that measure political opinions and voting intentions before and after German federal elections. The rolling cross-section design allows researchers to investigate how political campaigns, debates, media coverage and current events influence voters. Particularly valuable for understanding short-term changes in electoral preferences, campaign effects and political engagement during the 2010s and 2020s."
    },
    {
      "title": "European Social Survey (ESS) – Germany, Survey Rounds 2010–2023",
      "url_or_doi": "https://ess.nsd.no/en/series/321b06ad-1b98-4b7d-93ad-ca8a24e8788a",
      "justification": "A high-quality comparative survey conducted across European countries, including Germany. Provides data on political trust, democratic satisfaction, electoral participation, political interest, ideological self-placement, immigration attitudes, welfare preferences and social values. Researchers can select Germany and individual survey rounds to analyse political attitudes throughout the 2010s and early 2020s. Particularly useful for comparing German political developments with those in other European democracies."
    },
    {
      "title": "GESIS Panel – Longitudinal Survey of the German Population",
      "url_or_doi": "https://www.gesis.org/en/services/finding-and-accessing-data/german-survey-data",
      "justification": "A probability-based panel survey of the German population that began in 2013. Provides repeated measurements of individual attitudes and behaviours, including political opinions, social values and attitudes toward public policy. Particularly useful for studying how political preferences change within individuals over time, rather than simply comparing different cross-sectional samples. Offers opportunities to investigate political polarization, democratic attitudes and responses to major political and social events."
    },
    {
      "title": "Comparative Study of Electoral Systems (CSES) – German Election Studies 2013, 2017 and 2021",
      "url_or_doi": "https://cses.org/data-download/download-data-documentation/election-studies/",
      "justification": "An international election research project that includes German federal election surveys from 2013, 2017 and 2021. Contains harmonized information on voting behaviour, party identification, political efficacy, satisfaction with democracy, evaluations of political institutions and ideological attitudes. Particularly valuable for analysing German electoral behaviour within an international comparative framework and examining changes across successive elections."
    },
    {
      "title": "ARD DeutschlandTREND – German Political Opinion Surveys",
      "url_or_doi": "https://www.gesis.org/wahlen/laufende-erhebungen",
      "justification": "A long-running German public opinion survey series covering political attitudes and current political developments. Includes information on party preferences, satisfaction with government, political leadership, public policy priorities and evaluations of political institutions. Data from the 2010s and 2020s are relevant for studying changes in political trust, party competition and public responses to economic, social and political crises. GESIS provides access to archived survey datasets."
    },
    {
      "title": "Eurobarometer – German Public Opinion on Politics and European Integration",
      "url_or_doi": "https://www.gesis.org/en/eurobarometer-data-service",
      "justification": "A collection of European public opinion surveys that includes representative German samples throughout the 2010s and 2020s. Covers trust in national and European institutions, democratic satisfaction, European identity, attitudes toward EU integration, economic expectations, migration and political priorities. Particularly suitable for examining how German attitudes toward the European Union and national political institutions have evolved during major events such as the eurozone crisis, Brexit and the COVID-19 pandemic."
    },
    {
      "title": "German Federal and State Election Studies – GESIS Research Data Center Elections",
      "url_or_doi": "https://www.konsortswd.de/en/services/research/all-datacentres/fdz-wahlen/",
      "justification": "A research data collection covering German federal and state elections, including studies conducted during the 2010s and 2020s. Provides individual-level election survey data and related political opinion datasets. Relevant variables include voting decisions, electoral participation, political preferences and attitudes toward parties and candidates. Especially useful for comparing political behaviour across German federal states and examining regional differences in electoral support."
    },
    {
      "title": "GLES Panel – Longitudinal Political Attitudes and Voting Behaviour",
      "url_or_doi": "https://www.gesis.org/en/gles/data-and-documentation",
      "justification": "A longitudinal component of the German Longitudinal Election Study that repeatedly surveys individuals about their political attitudes and behaviour. Includes observations spanning the 2010s and 2020s. Particularly suitable for analysing changes in party identification, electoral preferences, political interest, ideological orientations and democratic attitudes at the individual level. The panel structure supports research on political socialization, partisan switching and the stability of political beliefs."
    },
    {
      "title": "GLES Candidate Studies – German Federal Elections 2013, 2017, 2021 and 2025",
      "url_or_doi": "https://www.gesis.org/en/gles/data-and-documentation",
      "justification": "A collection of surveys examining candidates standing in German federal elections. Covers candidates' political positions, policy preferences, recruitment backgrounds and campaign activities. Particularly useful for comparing the political attitudes of electoral candidates with those of the general population and investigating ideological differences between political parties. Provides an important complement to voter-focused surveys when studying political representation in Germany."
    },
    {
      "title": "German Government Public Opinion Surveys – Federal Press and Information Office",
      "url_or_doi": "https://www.gesis.org/wahlen/laufende-erhebungen",
      "justification": "Survey datasets commissioned by the German Federal Government and distributed through GESIS, including surveys conducted since 2014. These data provide information about public attitudes toward political and societal issues, government policies and contemporary political developments. Particularly relevant for examining how German citizens evaluate government actions and policy responses throughout the 2010s and 2020s."
    },
    {
      "title": "Politbarometer Annual Survey Collections – 2010s and 2020s",
      "url_or_doi": "https://www.gesis.org/en/elections/politbarometer",
      "justification": "Annual cumulative datasets from the German Politbarometer survey programme, providing more detailed information than the harmonized long-term dataset. Include voting intentions, evaluations of parties and politicians, preferred government coalitions, political issue priorities and responses to contemporary events. Especially useful for detailed investigations of individual years, including the 2013, 2017 and 2021 federal elections and major political developments during the 2020s."
    },
    {
      "title": "European Social Survey – Cross-National Political Attitudes and Behaviour",
      "url_or_doi": "https://www.europeansocialsurvey.org/",
      "justification": "The official European Social Survey project provides access to standardized survey data from Germany and other European countries. Its recurring political questions cover trust in politicians, political participation, democratic satisfaction, party preferences, political efficacy and ideological orientations. Rotating modules provide additional information on issues such as immigration, social justice and democratic values. Particularly suitable for analysing political attitudes in Germany between 2010 and the 2020s while controlling for broader European trends."
    }
  ]
}
